from qgis.PyQt.QtWidgets import QAction
mw = iface.mainWindow()
out = []
for w in mw.findChildren(QAction):
    t = w.text().replace('&','')
    if t and ('Broken' in t or 'broken' in w.objectName()):
        info = {'objectName': w.objectName(), 'text': t, 'tooltip': w.toolTip(), 'enabled': w.isEnabled(), 'visible': w.isVisible(), 'checkable': w.isCheckable(), 'checked': w.isChecked() if w.isCheckable() else None}
        parents = []
        for obj in w.associatedObjects():
            if obj.isWidgetType():
                chain = []
                p = obj
                while p is not None:
                    chain.append('%s(%s)' % (p.metaObject().className(), p.objectName()))
                    p = p.parentWidget()
                parents.append(' <- '.join(chain[:8]))
        info['associated'] = parents
        out.append(info)
result = out
"}

